import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA kernel source
# ----------------------------------------------------------------------
cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void conv1d_fp16_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    int N, int Cin, int Cout,
    int L, int K, int stride, int dilation,
    int L_out)
{
    int out_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (out_idx >= L_out) return;
    int n = blockIdx.z;
    int cout_idx = blockIdx.y;

    float acc = 0.0f;
    for (int cin = 0; cin < Cin; ++cin) {
        for (int k = 0; k < K; ++k) {
            int in_pos = out_idx * stride + k * dilation;
            int input_offset = ((n * Cin + cin) * L) + in_pos;
            int weight_offset = ((cout_idx * Cin + cin) * K) + k;
            acc += __half2float(input[input_offset]) * __half2float(weight[weight_offset]);
        }
    }
    if (bias != nullptr) {
        acc += __half2float(bias[cout_idx]);
    }
    output[((n * Cout + cout_idx) * L_out) + out_idx] = __float2half(acc);
}

torch::Tensor conv1d_fp16_forward(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias_opt,
    int stride,
    int dilation)
{
    const int N   = input.size(0);
    const int Cin = input.size(1);
    const int L   = input.size(2);
    const int Cout= weight.size(0);
    const int K   = weight.size(2);   // weight shape (Cout, Cin, K)

    const int L_out = (L - (K - 1) * dilation - 1) / stride + 1;

    auto output = torch::empty({N, Cout, L_out}, input.options());

    const dim3 block(128);
    const dim3 grid((L_out + block.x - 1) / block.x, Cout, N);

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(input.scalar_type(), "conv1d_fp16_forward", ([&] {
        const scalar_t* input_ptr  = input.data_ptr<scalar_t>();
        const scalar_t* weight_ptr = weight.data_ptr<scalar_t>();
        const scalar_t* bias_ptr   = nullptr;
        if (bias_opt.has_value()) {
            bias_ptr = bias_opt.value().data_ptr<scalar_t>();
        }
        scalar_t* output_ptr = output.data_ptr<scalar_t>();

        conv1d_fp16_kernel<scalar_t><<<grid, block>>>(
            input_ptr,
            weight_ptr,
            bias_ptr,
            output_ptr,
            N, Cin, Cout,
            L, K, stride, dilation,
            L_out);
    }));

    cudaDeviceSynchronize();
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv1d_fp16_forward", &conv1d_fp16_forward, "FP16 Conv1d forward (CUDA)");
}
'''

# ----------------------------------------------------------------------
# Compile the extension
# ----------------------------------------------------------------------
conv1d_ext = load_inline(
    name='conv1d_fp16_ext',
    cpp_sources='',
    cuda_sources=cuda_src,
    functions=['conv1d_fp16_forward'],
    verbose=False,
)

# ----------------------------------------------------------------------
# Model definition using the custom kernel
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for nn.Conv1d using a custom FP16 CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int,
                 kernel_size: int, stride: int = 1,
                 dilation: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.dilation = dilation

        # weight parameter (Cout, Cin, K) in FP16
        w = torch.empty(out_channels, in_channels, kernel_size, dtype=torch.float16)
        nn.init.kaiming_uniform_(w, a=math.sqrt(5))
        self.weight = nn.Parameter(w)

        if bias:
            b = torch.empty(out_channels, dtype=torch.float16)
            fan_in = in_channels * kernel_size
            bound = 1 / math.sqrt(fan_in)
            torch.nn.init.uniform_(b, -bound, bound)
            self.bias = nn.Parameter(b)
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure inputs are FP16 and on the same device as parameters
        if x.dtype != torch.float16:
            x = x.half()
        x = x.to(self.weight.device)

        bias = self.bias if self.bias is not None else None
        return conv1d_ext.conv1d_fp16_forward(
            x, self.weight, bias, self.stride, self.dilation
        )
